import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { syncBuiltinESMExports } from 'node:module';
import { createHash } from 'node:crypto';
import { createApp, defaultFixtureRoot } from './server/app.ts';
const url = '/api/file?source=Pi&path=workflow.md';
const original = fs.lstat;
fs.lstat = async () => { throw Object.assign(new Error('simulated filesystem I/O failure'), {code:'EIO'}); };
syncBuiltinESMExports();
let app = createApp(defaultFixtureRoot);
let r = await app.inject(url);
assert.equal(r.statusCode, 404);
console.log('PROBE lstat EIO: actual=404; PRD unexpected filesystem failure=500; body='+r.body);
await app.close();
fs.lstat = original;
syncBuiltinESMExports();
app = createApp(defaultFixtureRoot, {readFile: async () => { throw Object.assign(new Error('simulated deletion between stat and read'), {code:'ENOENT'}); }});
r = await app.inject(url);
assert.equal(r.statusCode, 500);
console.log('PROBE read ENOENT: actual=500; PRD missing file=404; body='+r.body);
await app.close();
let reads=0;
const bytes=Buffer.from([0xef,0xbb,0xbf,0x20,0x0d,0x0a,0xff]);
app=createApp(defaultFixtureRoot,{readFile: async () => {reads++;return bytes;}});
r=await app.inject(url);
assert.equal(r.statusCode,200);
assert.equal(reads,1);
assert.equal(r.json().content,bytes.toString('utf8'));
assert.equal(r.json().hash,createHash('sha256').update(bytes).digest('hex'));
assert.equal(r.headers['cache-control'],'no-store');
console.log('PROBE hash: one read; BOM/CRLF/non-UTF8 bytes hashed exactly; UTF8 content and no-store correct');
await app.close();
NODE
